impl NirIntrinsic {
    pub fn info(self) -> &'static NirIntrinsicInfo {
        &NIR_INTRINSIC_INFOS[self as usize]
    }

    /// Mesa's name (`nir_intrinsic_infos[op].name`).
    pub fn name(self) -> &'static str {
        self.info().name
    }

    /// The slot of the const index `idx`, if the intrinsic has it
    /// (`nir_intrinsic_info::index_map` less one).
    pub fn slot(self, idx: NirIndex) -> Option<usize> {
        self.info().indices.iter().find(|&&(i, _)| i == idx).map(|&(_, s)| s as usize)
    }
}
